package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.opensocket.aievent.core.issuetracking.recovery.*;
@Service public class OrderedProjectionWorkerService {private final ProjectionRecoveryRepository repo;private final ProjectionRecoveryEventLedger ledger;public OrderedProjectionWorkerService(ProjectionRecoveryRepository repo,ProjectionRecoveryEventLedger ledger){this.repo=repo;this.ledger=ledger;}
 @Transactional public List<ProjectionWorkClaim> claim(String tenant,String workerId,int leaseSeconds,int limit,String correlation){OffsetDateTime now=now();OffsetDateTime until=now.plusSeconds(Math.max(15,Math.min(leaseSeconds,900)));List<ProjectionWorkClaim> claims=new ArrayList<>();for(var due:repo.claimDueWork(req(tenant),now,lim(limit))){String token=UUID.randomUUID().toString();var claimed=copy(due,ProjectionWorkStatus.CLAIMED,due.attemptCount()+1,workerId,sha256(token),until,null,"","",due.version()+1,now);if(repo.saveWorkExpectedVersion(claimed,due.version())){adjustLaneCounters(tenant,due.laneId(),0,1,correlation);claims.add(new ProjectionWorkClaim(claimed,token,until));ledger.append(tenant,"PROJECTION_WORK",due.workId(),ProjectionRecoveryEventType.WORK_CLAIMED,workerId,"LEASE_ACQUIRED",json("claimUntil",until.toString()),correlation);}}return List.copyOf(claims);}
 @Transactional public OrderedProjectionWork acknowledge(String tenant,String workId,long expectedVersion,String claimToken,String actor,String correlation){var current=work(tenant,workId);verifyClaim(current,expectedVersion,claimToken);OffsetDateTime now=now();var next=copy(current,ProjectionWorkStatus.ACKNOWLEDGED,current.attemptCount(),"","",null,null,"","",current.version()+1,now);if(!repo.saveWorkExpectedVersion(next,current.version()))throw new IllegalStateException("PROJECTION_WORK_VERSION_CONFLICT");adjustLaneCounters(tenant,current.laneId(),-1,-1,correlation);ledger.append(tenant,"PROJECTION_WORK",workId,ProjectionRecoveryEventType.WORK_ACKNOWLEDGED,actor,"PROVIDER_CONFIRMED","{}",correlation);return next;}
 @Transactional public OrderedProjectionWork retry(String tenant,String workId,long expectedVersion,String claimToken,String actor,String failureCode,String safeMessage,int retryAfterSeconds,String correlation){var current=work(tenant,workId);verifyClaim(current,expectedVersion,claimToken);OffsetDateTime now=now();boolean exhausted=current.attemptCount()>=current.maxAttempts();ProjectionWorkStatus status=exhausted?ProjectionWorkStatus.DEAD_LETTER:ProjectionWorkStatus.RETRY_WAITING;var next=copy(current,status,current.attemptCount(),"","",null,exhausted?null:now.plusSeconds(Math.max(5,Math.min(retryAfterSeconds,3600))),blank(failureCode),blank(safeMessage),current.version()+1,now);if(!repo.saveWorkExpectedVersion(next,current.version()))throw new IllegalStateException("PROJECTION_WORK_VERSION_CONFLICT");adjustLaneCounters(tenant,current.laneId(),exhausted?-1:0,-1,correlation);ledger.append(tenant,"PROJECTION_WORK",workId,exhausted?ProjectionRecoveryEventType.WORK_DEAD_LETTERED:ProjectionRecoveryEventType.WORK_RETRY_SCHEDULED,actor,blank(failureCode),json("status",status.name()),correlation);return next;}
 @Transactional public int recoverExpiredClaims(String tenant,int limit,String actor,String reason,String correlation){int recovered=0;OffsetDateTime now=now();for(var stale:repo.listExpiredClaims(req(tenant),now,lim(limit))){boolean exhausted=stale.attemptCount()>=stale.maxAttempts();ProjectionWorkStatus status=exhausted?ProjectionWorkStatus.DEAD_LETTER:ProjectionWorkStatus.RETRY_WAITING;var next=copy(stale,status,stale.attemptCount(),"","",null,exhausted?null:now.plusSeconds(5),"WORKER_LEASE_EXPIRED","Worker lease expired before acknowledgement.",stale.version()+1,now);if(repo.saveWorkExpectedVersion(next,stale.version())){recovered++;adjustLaneCounters(tenant,stale.laneId(),exhausted?-1:0,-1,correlation);ledger.append(tenant,"PROJECTION_WORK",stale.workId(),exhausted?ProjectionRecoveryEventType.WORK_DEAD_LETTERED:ProjectionRecoveryEventType.WORK_RETRY_SCHEDULED,actor,requiredReason(reason),json("previousOwner",stale.claimOwner()),correlation);}}return recovered;}
 private void adjustLaneCounters(String tenant,String laneId,int queuedDelta,int inflightDelta,String correlation){for(int i=0;i<3;i++){var lane=repo.findLane(tenant,laneId).orElseThrow(()->new IllegalStateException("Projection lane not found."));OffsetDateTime now=now();var next=new OrderedProjectionLane(lane.tenantId(),lane.laneId(),lane.aggregateKey(),lane.laneType(),lane.connectionId(),lane.projectMappingId(),lane.status(),lane.nextSequence(),lane.activeGeneration(),lane.maxQueueDepth(),Math.max(0,lane.queuedCount()+queuedDelta),Math.max(0,lane.inFlightCount()+inflightDelta),lane.version()+1,lane.createdAt(),now,correlation);if(repo.saveLaneExpectedVersion(next,lane.version()))return;}throw new IllegalStateException("PROJECTION_LANE_VERSION_CONFLICT");}
 private OrderedProjectionWork work(String tenant,String id){return repo.findWork(req(tenant),req(id)).orElseThrow(()->new IllegalArgumentException("Projection work not found."));}private void verifyClaim(OrderedProjectionWork v,long expected,String token){if(v.version()!=expected)throw new IllegalStateException("PROJECTION_WORK_VERSION_CONFLICT");if(v.status()!=ProjectionWorkStatus.CLAIMED&&v.status()!=ProjectionWorkStatus.IN_PROGRESS)throw new IllegalStateException("PROJECTION_WORK_NOT_CLAIMED");if(token==null||token.isBlank()||!constant(v.claimTokenHash(),sha256(token)))throw new IllegalStateException("PROJECTION_WORK_CLAIM_TOKEN_INVALID");if(v.claimUntil()==null||v.claimUntil().isBefore(now()))throw new IllegalStateException("PROJECTION_WORK_CLAIM_EXPIRED");}
 private OrderedProjectionWork copy(OrderedProjectionWork v,ProjectionWorkStatus status,int attempts,String owner,String tokenHash,OffsetDateTime until,OffsetDateTime next,String code,String message,long version,OffsetDateTime now){return new OrderedProjectionWork(v.tenantId(),v.workId(),v.laneId(),v.laneSequence(),v.generation(),v.operationType(),status,v.aggregateId(),v.outboxId(),v.projectionId(),v.payloadHash(),v.coalesceKey(),v.dependsOnWorkId(),v.supersededByWorkId(),v.externalIdempotencyMarker(),attempts,v.maxAttempts(),owner,tokenHash,until,next,code,message,version,v.createdAt(),now,v.correlationId());}
 private String sha256(String value){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(b);}catch(Exception e){throw new IllegalStateException("SHA-256 unavailable.",e);}}private boolean constant(String a,String b){return a!=null&&b!=null&&MessageDigest.isEqual(a.getBytes(StandardCharsets.US_ASCII),b.getBytes(StandardCharsets.US_ASCII));}private String json(String k,String v){String s=v==null?"":v.replace("\\","\\\\").replace("\"","'");return "{\""+k+"\":\""+s+"\"}";}private String requiredReason(String v){String s=req(v);if(s.length()<8)throw new IllegalArgumentException("Governance reason must contain at least 8 characters.");return s;}private String req(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value missing.");return v.trim();}private String blank(String v){return v==null?"":v.trim();}private int lim(int n){return Math.max(1,Math.min(n,500));}private OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.UTC);} }
